let {onkey,onpeek,disabled=false}:{onkey:(key:string)=>void,onpeek:()=>void,disabled?:boolean}=$props();let pressed=$state<string>(ui.c019);function press(key:string){pressed=key;onkey(key);setTimeout(()=>pressed=ui.c019,150)}</script><div class="keyboard" aria-label={ui.c199}>{#each [ui.c200,ui.c201,ui.c202] as row}<div class="keyrow">{#each row.split(ui.c019) as key}<button class="key" class:pressed={pressed===key} {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div>{/each}<div class="keyrow"><button class="peek" {disabled} onclick={onpeek}>{ui.c203}</button>{#each ui.c204.split(ui.c019) as key}<button class="number-key" {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div></div>
